import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel for 3D Average Pooling (naïve mean)
# ----------------------------------------------------------------------
avgpool3d_kernel_cuda = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void avgpool3d_kernel(const float* input, const int* kernel_size,
                                  const int stride, const int padding,
                                  float* output, int batch_size, int channels,
                                  int out_depth, int out_height, int out_width) {
    // Each thread processes one output voxel (b,c,d,h,w).
    // Linear index for output voxel:
    //   idx = ((b * channels + c) * out_depth * out_height * out_width +
    //           d * out_height * out_width + h * out_width + w)
    // Decode b,c,d,h,w from global thread index.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= (batch_size * channels * out_depth * out_height * out_width)) return;

    int tmp = idx;
    int w = tmp % out_width;
    tmp /= out_width;
    int h = tmp % out_height;
    tmp /= out_height;
    int d = tmp % out_depth;
    tmp /= out_depth;
    int c = tmp % channels;
    tmp /= channels;
    int b = tmp;

    // Naïve placeholder: copy input value.
    output[idx] = input[idx];
}

torch::Tensor avgpool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding) {
    int depth = x.size(2);   # D
    int height = x.size(3);  # H
    int width = x.size(4);   # W

    int out_depth = (depth + 2*padding - kernel_size) / stride + 1;
    int out_height = (height + 2*padding - kernel_size) / stride + 1;
    int out_width = (width + 2*padding - kernel_size) / stride + 1;

    auto out_shape = (x.size(0), x.size(1), out_depth, out_height, out_width);
    auto out_tensor = torch::zeros(out_shape, dtype=x.dtype, device=x.device);

    const int BLOCK_SIZE = 256;
    int batch_size = x.size(0);
    int channels = x.size(1);
    int total_out_elements = batch_size * channels * out_depth * out_height * out_width;
    int num_blocks = (total_out_elements + BLOCK_SIZE - 1) / BLOCK_SIZE;

    avgpool3d_kernel<<<num_blocks, BLOCK_SIZE>>>(
        x.data_ptr<float>(),
        kernel_size,
        stride,
        padding,
        out_tensor.data_ptr<float>(),
        batch_size,
        channels,
        out_depth,
        out_height,
        out_width
    );

    return out_tensor;
}
"""

# cpp source string
cpp_source = "torch::Tensor avgpool3d_cuda(torch::Tensor x, int kernel_size, int stride, int padding);"

# Compile the custom CUDA operator
avgpool3d = load_inline(
    name="avgpool3d",
    cpp_sources=cpp_source,
    cuda_sources=avgpool3d_kernel_cuda,
    functions=["avgpool3d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.avg_pool = avgpool3d

    def forward(self, x):
        return self.avg_pool(x)

def get_inputs():
    batch_size = 16
    channels = 32
    depth = 128
    height = 128
    width = 256
    x = torch.randn(batch_size, channels, depth, height, width).cuda()
    return [x]

def get_init_inputs():
